	})
	for _, tc := range []struct {
		target  string
		wantErr string
	}{
		{"", "dataset name is required"},
		{"ghost", "dataset not found: ghost"},
	} {
		out, err := ExportUpstreamLineage(graph, tc.target)
		if err == nil {
			t.Fatalf("ExportUpstreamLineage(%q) succeeded with %q", tc.target, out)
		}
		if err.Error() != tc.wantErr {
			t.Errorf("target %q: error = %q, want %q", tc.target, err, tc.wantErr)
		}
		if out != "" {
			t.Errorf("target %q returned partial content %q", tc.target, out)
		}
	}
}

// Valid names with multibyte text, emoji, JSON-special characters and a real
// replacement character (U+FFFD) export normally and decode back to exactly
// the registered values. The real U+FFFD rune must not be mistaken for a bad
// byte, even though a lone 0xff byte in another dataset is one.
func TestExportUpstreamLineageRoundTripsUnusualValidNames(t *testing.T) {
	chinese := "数据集"
	emoji := "report 🚀"
	replacement := "repaired�name"
	loneFF := "lone\xff"
	graph := buildRegisteredGraph(t, [][]string{
		{chinese},
		{emoji, chinese},
		{replacement, emoji},
		{loneFF}, // invalid name registered, but never in replacement's closure
	})

	out := mustExport(t, graph, replacement)
	doc := parseExport(t, out)
	wantNodes := []string{chinese, emoji, replacement}
	wantNodesSorted := append([]string(nil), wantNodes...)
	sortStringsCopy(wantNodesSorted)
	assertStringSlicesEqual(t, doc.Nodes, wantNodesSorted)
	for _, want := range wantNodes {
		found := false
		for _, got := range doc.Nodes {
			if got == want {
				found = true
			}
		}
		if !found {
			t.Errorf("name %q did not round-trip; nodes = %q", want, doc.Nodes)
		}
	}

	// The valid U+FFFD name alone exports and survives the JSON round trip,
	// while the name built from an actual invalid byte is rejected: the two
	// never collapse into the same documented node.
	solo := buildRegisteredGraph(t, [][]string{{replacement}})
	soloOut := mustExport(t, solo, replacement)
	if !strings.Contains(soloOut, replacement) {
		t.Errorf("export %q must contain the real U+FFFD name verbatim", soloOut)
	}
	if _, err := ExportUpstreamLineage(buildRegisteredGraph(t, [][]string{{loneFF}}), loneFF); err == nil {
		t.Fatal("name with a lone 0xff byte must not export")
	}
}

// sortStringsCopy and assertStringSlicesEqual keep the unusual-names test
// self-contained without repeating the reflection imports of other files.
func sortStringsCopy(in []string) {
	for i := 1; i < len(in); i++ {
		for j := i; j > 0 && in[j-1] > in[j]; j-- {
			in[j-1], in[j] = in[j], in[j-1]
		}
	}
}

func assertStringSlicesEqual(t *testing.T, got, want []string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("nodes = %q, want %q", got, want)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Fatalf("nodes = %q, want %q", got, want)
		}
	}
}

